/**
 * frpc configuration generation.
 *
 * The generated file is derived state, never user-edited: it is rewritten from
 * the plugin config plus the port DSH actually bound on every start.
 */
import { LIMITS } from './config-values.js'

/** Encodes one TOML basic string. */
export function tomlString(value) {
  const text = String(value ?? '')
  let out = '"'
  for (const char of text) {
    const code = char.codePointAt(0)
    if (char === '"') out += '\\"'
    else if (char === '\\') out += '\\\\'
    else if (char === '\n') out += '\\n'
    else if (char === '\r') out += '\\r'
    else if (char === '\t') out += '\\t'
    else if (code !== undefined && (code < 0x20 || code === 0x7f)) out += `\\u${code.toString(16).padStart(4, '0')}`
    else out += char
  }
  return `${out}"`
}

/** Rejects values that would corrupt a line-oriented INI file. */
export function iniValue(value) {
  return String(value ?? '').replace(/[\r\n]/g, ' ')
}

/**
 * Parses the port out of a URL origin such as `http://127.0.0.1:13162`.
 * @param {string} origin - the origin reported by the host.
 * @returns {number} the port, or 0 when it cannot be read.
 */
export function portOfOrigin(origin) {
  if (typeof origin !== 'string' || origin === '') return 0
  try {
    const url = new URL(origin)
    if (url.port !== '') return Number.parseInt(url.port, 10)
    return url.protocol === 'https:' ? 443 : 80
  } catch {
    return 0
  }
}

/** The loopback host part of an origin, falling back to `127.0.0.1`. */
export function hostOfOrigin(origin, fallback = '127.0.0.1') {
  if (typeof origin !== 'string' || origin === '') return fallback
  try {
    // URL.hostname keeps IPv6 brackets; frpc wants the bare literal.
    return new URL(origin).hostname.replace(/^\[(.*)\]$/, '$1') || fallback
  } catch {
    return fallback
  }
}

/**
 * Validates everything the generated file depends on.
 * @param {object} input - generation inputs.
 * @returns {string[]} human-readable problems; empty means usable.
 */
export function validateTunnelTarget(input) {
  const problems = []
  if (!input.serverAddr?.trim()) problems.push('frp server address is empty')
  if (!input.token?.trim()) problems.push('frp token is not set')
  if (!Number.isInteger(input.localPort) || input.localPort < 1 || input.localPort > 65535) {
    problems.push('local DSH port is unknown')
  }
  if (!Number.isInteger(input.remotePort) || input.remotePort < 1 || input.remotePort > 65535) {
    problems.push('remote port is invalid')
  }
  if (!/^[A-Za-z0-9_.-]{1,64}$/.test(String(input.proxyName ?? ''))) problems.push('proxy name is invalid')
  return problems
}

const HEADER = [
  '# Generated by dsh-tunnel. Do not edit: it is rewritten from plugin',
  '# configuration and the port DSH actually bound, on every start.',
]

/**
 * Builds the frpc configuration text.
 *
 * The token is only ever placed in this file (or in the child environment for
 * the templated form); callers must treat the result as a secret.
 * @param {object} input - generation inputs.
 * @param {string} input.format - `toml` or `ini`.
 * @param {string} input.serverAddr - frps host.
 * @param {number} input.serverPort - frps control port.
 * @param {string} input.token - frp auth token, or a `{{ .Envs.X }}` template.
 * @param {boolean} input.tls - enable transport TLS.
 * @param {string} [input.tlsServerName] - TLS ServerName override.
 * @param {string} input.localHost - loopback target host.
 * @param {number} input.localPort - the port DSH bound.
 * @param {number} input.remotePort - the port frps exposes internally.
 * @param {string} input.proxyName - proxy name.
 * @returns {string} the configuration text, newline-terminated.
 */
export function buildFrpcConfig(input) {
  const problems = validateTunnelTarget(input)
  if (problems.length > 0) throw new Error(`Cannot generate frpc config: ${problems.join('; ')}`)
  const lines = [...HEADER, '']
  if (input.format === 'ini') {
    lines.push('[common]')
    lines.push(`server_addr = ${iniValue(input.serverAddr)}`)
    lines.push(`server_port = ${input.serverPort}`)
    lines.push(`token = ${iniValue(input.token)}`)
    lines.push(`tls_enable = ${input.tls ? 'true' : 'false'}`)
    if (input.tls && input.tlsServerName) lines.push(`tls_server_name = ${iniValue(input.tlsServerName)}`)
    lines.push('login_fail_exit = false')
    lines.push('')
    lines.push(`[${input.proxyName}]`)
    lines.push('type = tcp')
    lines.push(`local_ip = ${iniValue(input.localHost)}`)
    lines.push(`local_port = ${input.localPort}`)
    lines.push(`remote_port = ${input.remotePort}`)
    lines.push('')
    return lines.join('\n')
  }
  lines.push(`serverAddr = ${tomlString(input.serverAddr)}`)
  lines.push(`serverPort = ${input.serverPort}`)
  lines.push('loginFailExit = false')
  lines.push('')
  lines.push('auth.method = "token"')
  lines.push(`auth.token = ${tomlString(input.token)}`)
  lines.push('')
  lines.push(`transport.tls.enable = ${input.tls ? 'true' : 'false'}`)
  if (input.tls && input.tlsServerName) lines.push(`transport.tls.serverName = ${tomlString(input.tlsServerName)}`)
  lines.push('')
  lines.push('[[proxies]]')
  lines.push(`name = ${tomlString(input.proxyName)}`)
  lines.push('type = "tcp"')
  lines.push(`localIP = ${tomlString(input.localHost)}`)
  lines.push(`localPort = ${input.localPort}`)
  lines.push(`remotePort = ${input.remotePort}`)
  lines.push('')
  return lines.join('\n')
}

/** The file name the generated config is written to. */
export function frpcConfigFileName(format) {
  return format === 'ini' ? 'frpc.ini' : 'frpc.toml'
}

/** Maximum proxy name length enforced by frp. */
export const MAX_PROXY_NAME = LIMITS.proxyName
